app.MapGet("/files/{filename}", async (string filename, string webRoot) =>
{
    var filePath = Path.Combine(webRoot, "uploads", filename);
    // If filename is ../../../../etc/passwd, this escapes the directory
    if (!System.IO.File.Exists(filePath))
        return Results.NotFound();

    var content = await System.IO.File.ReadAllTextAsync(filePath);
    return Results.Text(content);
});

app.MapGet("/files/{id}", async (int id, AppDbContext db, IWebHostEnvironment env) =>
{
    var fileRecord = await db.UploadedFiles.FindAsync(id);
    if (fileRecord == null) return Results.NotFound();

    var basePath = Path.GetFullPath(Path.Combine(env.WebRootPath, "uploads"));
    var fullPath = Path.GetFullPath(Path.Combine(basePath, fileRecord.StoredFileName));

    if (!fullPath.StartsWith(basePath, StringComparison.Ordinal))
        return Results.Forbid(); // Path traversal attempt

    var contentType = fileRecord.ContentType ?? "application/octet-stream";
    return Results.File(fullPath, contentType, fileRecord.OriginalFileName);
});

app.MapPost("/api/upload", async (IFormFile file, AppDbContext db, IWebHostEnvironment env) =>
{
    var allowedExtensions = new[] { ".jpg", ".png", ".pdf" };
    var extension = Path.GetExtension(file.FileName).ToLowerInvariant();

    if (!allowedExtensions.Contains(extension))
        return Results.BadRequest("File type not allowed");

    var newFileName = Guid.NewGuid().ToString() + extension;
    var savePath = Path.Combine(env.WebRootPath, "uploads", newFileName);

    await using var stream = new FileStream(savePath, FileMode.Create);
    await file.CopyToAsync(stream);

    await db.UploadedFiles.AddAsync(new UploadedFile
    {
        OriginalFileName = file.FileName,
        StoredFileName = newFileName,
        ContentType = file.ContentType,
        Size = file.Length
    });
    await db.SaveChangesAsync();

    return Results.Ok(new { id = 1 });
});

function UploadForm() {
  const [file, setFile] = useState(null);

  async function handleSubmit(e) {
    e.preventDefault();
    const formData = new FormData();
    formData.append('file', file);

    const response = await fetch('/api/upload', {
      method: 'POST',
      body: formData
    });

    if (response.ok) {
      alert('Upload successful');
    } else {
      const error = await response.json();
      alert(error);
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <input type="file" onChange={(e) => setFile(e.target.files[0])} />
      <button type="submit">Upload</button>
    </form>
  );
}
